// packages/ui/src/Button/Button.recipe.tsx
// Covers: Button, IconButton, PlainButton

/**
 * Button: an action the user takes: save, publish, delete, open a menu.
 * `default` is the main action of a view (one per view), `base` a secondary
 * one, `danger` one that deletes or can't be undone: filled, it is the
 * confirm dialog's button, and on a list row a delete is as quiet as the
 * row's other actions. `look="ghost"` makes any of them quiet, for toolbars
 * and rows, where an action is an IconButton with a tooltip. IconButton is
 * an action shown as an icon alone; PlainButton makes a non-button element,
 * like an info icon or an avatar, act as a button.
 *
 * When not to use:
 * - Going to another page: Link. In the Next app, a route is the app's
 *   NextLink, and one that must look like a button is
 *   `Button as={NextLink}`.
 * - A toggle that shows whether it's on: Chip.
 * - Two `default` buttons in one view: make the lesser one `base`.
 *
 * Pitfalls:
 * - `type` defaults to "button". A form's submit needs `type="submit"`.
 * - Deleting a row removes the button that had focus: move focus on, to a
 *   stable button, with a `ref`.
 * - IconButton needs a `tooltip`; a string one is its accessible name. Add
 *   `aria-label` or `aria-labelledby` only when the name must differ from
 *   what the tooltip shows, like "Delete Design review" under "Delete".
 * - Say why a button can't be used: `disabledWithReason`,
 *   `readOnlyWithReason`, `loadingWithReason`. A bare `disabled` leaves the
 *   user guessing.
 */
import { Avatar } from '@packages/ui/Avatar';
import { Button, IconButton, PlainButton } from '@packages/ui/Button';
import { Controller, Form } from '@packages/ui/Form';
import { Input } from '@packages/ui/Input';
import { Copy, Info, Play, Plus, Settings, Trash2 } from 'lucide-react';
import React, { useEffect, useId, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const saveEvent = (draft: EventDraft) =>
  new Promise<EventDraft>((resolve) => setTimeout(() => resolve(draft), 800));

// Usage: the patterns to copy.
type EventDraft = { title: string };

/**
 * Saving a form: `type="submit"` makes the button send the form, and
 * `loading` follows `formState.isSubmitting`, so it can't be pressed twice.
 * The result is announced through a status region.
 */
const SaveForm = () => {
  const [saved, setSaved] = useState('');
  const { control, handleSubmit, reset, formState } = useForm<EventDraft>({
    defaultValues: { title: '' },
  });

  return (
    <Form
      onSubmit={handleSubmit(async (draft) => {
        const result = await saveEvent(draft);
        setSaved(`Saved "${result.title}"`);
      })}
      actions={
        <>
          <Button variant="base" onClick={() => reset()}>
            Reset
          </Button>
          <Button
            type="submit"
            // Saving takes a moment and the status above reports the result.
            loading={formState.isSubmitting}
          >
            Save
          </Button>
        </>
      }
    >
      <Controller
        name="title"
        control={control}
        rules={{ required: 'Enter the event title' }}
      >
        {({ field }) => (
          <Input label="Event title" autoComplete="off" {...field} />
        )}
      </Controller>
      <p role="status">{saved}</p>
    </Form>
  );
};

/** A form's actions: the main one last, the secondary one `base`. */
const FormActions = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button variant="base">Cancel</Button>
    <Button>Publish</Button>
  </div>
);

/**
 * Icons: `leftIcon` before the label, `rightIcon` after it. Icons are
 * decoration; the text names the button.
 */
const WithIcons = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button leftIcon={<Plus />}>New event</Button>
    <Button variant="base" rightIcon={<Play />}>
      Start session
    </Button>
  </div>
);

/**
 * A key hint: `rightAddOn` takes an element, hidden from screen readers
 * because `aria-keyshortcuts` announces the key. The shortcut itself must
 * work, so a key listener runs the action.
 */
const WithShortcut = () => {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement;
      if (event.key !== 'n' || event.ctrlKey || event.metaKey) return;
      if (target.closest('input, textarea, [contenteditable]')) return;
      setCount((current) => current + 1);
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  return (
    <div className="flex-col-gap-2 items-start">
      <Button
        aria-keyshortcuts="N"
        rightAddOn={<kbd aria-hidden>N</kbd>}
        onClick={() => setCount((current) => current + 1)}
      >
        New event
      </Button>
      <p role="status">Events created: {count}</p>
    </div>
  );
};

/**
 * Tooltip: detail on hover and focus, read as the description. With a
 * disabled reason, both show, the tooltip first.
 */
const WithTooltip = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button tooltip="Sends the event to every subscriber">Publish</Button>
    <Button
      tooltip="Sends the event to every subscriber"
      disabledWithReason="Add a date before publishing"
    >
      Publish
    </Button>
  </div>
);

/**
 * Unavailable: `disabledWithReason` disables it and says why. Read-only
 * (`readOnlyWithReason`) keeps the button visible but inert, for a view the
 * user may not change.
 */
const Unavailable = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button disabledWithReason="Add a date before publishing">Publish</Button>
    <Button readOnlyWithReason="Only organizers can edit the schedule">
      Edit schedule
    </Button>
    <Button
      // The page shows no draft yet, so the reason is plain.
      disabled
    >
      Discard draft
    </Button>
  </div>
);

/**
 * Busy: `loading` shows a spinner in place of the icon and the button can't
 * be pressed again until it's done. `loadingWithReason` also says what is
 * happening, to sighted users on hover and in a status region for screen
 * readers. Set one of the two, not both.
 */
const Busy = () => {
  const [syncing, setSyncing] = useState(false);

  return (
    <div className="flex-row-gap-2 flex-wrap">
      <Button
        loadingWithReason={syncing ? 'Syncing the attendee list' : undefined}
        onClick={() => {
          setSyncing(true);
          setTimeout(() => setSyncing(false), 1500);
        }}
      >
        Sync attendees
      </Button>
      <Button loadingWithReason="Exporting the guest list">
        Export guests
      </Button>
    </div>
  );
};

/**
 * Play and stop in one button: `disableWhileLoading={false}` keeps it
 * pressable while loading, so the press that started it can stop it.
 */
const RunAndStop = () => {
  const [running, setRunning] = useState(false);

  return (
    <Button
      leftIcon={<Play />}
      // It stays pressable, and the label changes to Stop.
      loading={running}
      disableWhileLoading={false}
      onClick={() => setRunning(!running)}
    >
      {running ? 'Stop' : 'Run'}
    </Button>
  );
};

/**
 * Keeping focus after a delete: the removed row's button disappears, so a
 * `ref` on a stable button moves focus there.
 */
const DeleteRow = () => {
  const [sessions, setSessions] = useState(['Opening keynote', 'Workshop']);
  const addRef = useRef<HTMLButtonElement>(null);

  return (
    <div className="flex-col-gap-2 items-start">
      <ul aria-label="Sessions" className="flex-col-gap-2">
        {sessions.map((session) => (
          <li key={session} className="flex-row-gap-2 items-center">
            {session}
            <IconButton
              variant="danger"
              look="ghost"
              tooltip="Delete"
              aria-label={`Delete ${session}`}
              onClick={() => {
                addRef.current?.focus();
                setSessions((current) =>
                  current.filter((entry) => entry !== session),
                );
              }}
            >
              <Trash2 />
            </IconButton>
          </li>
        ))}
      </ul>
      <Button
        ref={addRef}
        leftIcon={<Plus />}
        onClick={() => setSessions((current) => [...current, 'New session'])}
      >
        Add session
      </Button>
    </div>
  );
};

/**
 * Icon only: IconButton, named by its `tooltip`, which shows on hover and
 * focus. Sizes `xs`, `sm` (the default) and `md`. `loading` and
 * `disabledWithReason` work as on Button.
 */
const IconOnly = () => (
  <div className="flex-row-gap-2 flex-wrap items-center">
    <IconButton variant="base" look="ghost" size="xs" tooltip="Event settings">
      <Settings />
    </IconButton>
    <IconButton variant="base" tooltip="Event settings">
      <Settings />
    </IconButton>
    <IconButton size="md" variant="danger" tooltip="Delete event">
      <Trash2 />
    </IconButton>
    <IconButton loadingWithReason="Duplicating event" tooltip="Duplicate event">
      <Copy />
    </IconButton>
    <IconButton
      disabledWithReason="Cancelled events can't be copied"
      tooltip="Duplicate event"
    >
      <Copy />
    </IconButton>
  </div>
);

/**
 * A name that differs from the tooltip: `aria-labelledby` points at visible
 * text, here the row's title, and `aria-label` gives a fuller name, like
 * "Duplicate Design review" under the tooltip "Duplicate".
 */
const IconNames = () => {
  const titleId = useId();

  return (
    <div className="flex-row-gap-2 items-center">
      <span id={titleId}>Design review</span>
      <IconButton aria-labelledby={titleId} tooltip="Settings">
        <Settings />
      </IconButton>
      <IconButton aria-label="Duplicate Design review" tooltip="Duplicate">
        <Copy />
      </IconButton>
    </div>
  );
};

/**
 * An info icon that shows details below it: PlainButton makes its one child,
 * a non-interactive element, focusable and pressable by Enter and Space, with
 * the look the child already has, its focus style included. Name it with
 * `aria-label`; `aria-expanded` and `aria-controls` say what it opens. For a
 * styled action use IconButton.
 */
const InfoIcon = () => {
  const [open, setOpen] = useState(false);
  const detailsId = useId();

  return (
    <div className="flex-col-gap-2 items-start">
      <PlainButton
        aria-label="About ticket types"
        aria-expanded={open}
        aria-controls={detailsId}
        onClick={() => setOpen(!open)}
      >
        <span>
          <Info aria-hidden />
        </span>
      </PlainButton>
      <p id={detailsId} hidden={!open}>
        VIP includes the speaker dinner.
      </p>
    </div>
  );
};

/**
 * An avatar that does something when pressed, like showing a person's
 * details. Avatar hides itself from assistive tech, so the `span` around it
 * is the button, and `aria-label` names it.
 */
const OrganizerAvatar = () => {
  const [contact, setContact] = useState('');

  return (
    <div className="flex-row-gap-2 items-center">
      <PlainButton
        aria-label="Show contact details for Grace Hopper"
        onClick={() => setContact('Grace Hopper, grace@example.com')}
      >
        <span>
          <Avatar name="Grace Hopper" />
        </span>
      </PlainButton>
      <p role="status">{contact}</p>
    </div>
  );
};

export default function ButtonRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <SaveForm />
      <FormActions />
      <WithIcons />
      <WithShortcut />
      <WithTooltip />
      <Unavailable />
      <Busy />
      <RunAndStop />
      <DeleteRow />
      <IconOnly />
      <IconNames />
      <InfoIcon />
      <OrganizerAvatar />
    </div>
  );
}

// packages/ui/src/Dropdown/Dropdown.recipe.tsx
// Covers: Dropdown

/**
 * Dropdown: a menu of actions or choices behind a trigger button, with menu
 * roles, focus and keyboard built in (arrows, typeahead, Escape). Write a row
 * as a `Dropdown.Item`, an on/off row as a `Dropdown.CheckboxItem`, one
 * choice of several as a `Dropdown.RadioItem` in a `Dropdown.RadioGroup`.
 * Group rows with `Dropdown.Group`, open a submenu from a `Dropdown.Item`
 * inside `Dropdown.SubMenu`. `showCheckbox` and `showCheckmark` set how
 * checked rows show. The trigger is one focusable element that forwards its
 * props: `Dropdown.Button`, an `IconButton` named for what the menu holds,
 * or for an avatar a `PlainButton` around the Avatar, as the Avatar recipe
 * shows; never an Avatar inside an IconButton. Tab closes the menu, back to
 * the trigger.
 *
 * Not for navigation (use `Link`, the app's NextLink for its routes), one
 * on/off toggle (`Button` or `Chip`), a form value (`Select`) or free-form
 * content (`Popover`).
 *
 * Pitfalls: an `onSelect` that calls `event.preventDefault()` keeps the menu
 * open; an item whose children aren't plain text needs `textValue`; a menu
 * holds only items, so no buttons or links inside it.
 */
import { Avatar } from '@packages/ui/Avatar';
import { IconButton } from '@packages/ui/Button';
import { Dropdown } from '@packages/ui/Dropdown';
import {
  ArrowUpDown,
  Copy,
  Ellipsis,
  Link,
  Pencil,
  Trash2,
  UserPlus,
} from 'lucide-react';
import React, { useState } from 'react';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const event: EventRow = { id: 'e1', name: 'Design Summit' };

const speakers = ['Ada Lovelace', 'Grace Hopper', 'Alan Turing'];

const fakeSave = () => new Promise<void>((resolve) => setTimeout(resolve, 800));

// Usage: the patterns to copy.
type EventRow = { id: string; name: string };

/**
 * Actions on a table row. An `IconButton` trigger is named per row, so a
 * screen reader hears which event the menu is for; its `tooltip` shows the
 * short name. Each item runs its own `onSelect` once.
 */
const RowActions = ({ row }: { row: EventRow }) => {
  const [status, setStatus] = useState('');

  return (
    <div className="flex-row-gap-2 items-center">
      <Dropdown
        menu={
          <>
            <Dropdown.Item
              leftIcon={<Pencil />}
              onSelect={() => setStatus(`Renaming ${row.name}`)}
            >
              Rename
            </Dropdown.Item>
            <Dropdown.Item
              leftIcon={<Copy />}
              onSelect={() => setStatus(`Duplicated ${row.name}`)}
            >
              Duplicate
            </Dropdown.Item>
            <Dropdown.Separator />
            <Dropdown.Item
              leftIcon={<Trash2 />}
              onSelect={() => setStatus(`Cancelled ${row.name}`)}
            >
              Cancel event
            </Dropdown.Item>
          </>
        }
      >
        <IconButton
          variant="base"
          look="ghost"
          aria-label={`Actions for ${row.name}`}
          tooltip="Actions"
        >
          <Ellipsis />
        </IconButton>
      </Dropdown>
      <p role="status">{status}</p>
    </div>
  );
};

/**
 * Groups, a separator and a submenu. A `Dropdown.Group` without a `label`
 * only sets rows apart; the submenu's trigger is a `Dropdown.Item`, which gets
 * the chevron. `disabledWithReason` keeps an item or submenu visible and says
 * why it can't be used.
 */
const EventMenu = () => {
  const [status, setStatus] = useState('');

  return (
    <div className="flex-row-gap-2 items-center">
      <Dropdown
        menu={
          <>
            <Dropdown.Group label="Edit">
              <Dropdown.Item
                leftIcon={<Pencil />}
                onSelect={() => setStatus('Renaming the event')}
              >
                Rename
              </Dropdown.Item>
              <Dropdown.Item
                leftIcon={<Copy />}
                onSelect={() => setStatus('Event duplicated')}
              >
                Duplicate
              </Dropdown.Item>
            </Dropdown.Group>
            <Dropdown.Separator />
            <Dropdown.Group>
              <Dropdown.SubMenu
                menu={
                  <>
                    <Dropdown.Item
                      leftIcon={<Link />}
                      onSelect={() => setStatus('Link copied')}
                    >
                      Copy link
                    </Dropdown.Item>
                    <Dropdown.Item
                      leftIcon={<UserPlus />}
                      disabledWithReason="Only organizers can invite attendees"
                    >
                      Invite attendees
                    </Dropdown.Item>
                  </>
                }
              >
                <Dropdown.Item>Share</Dropdown.Item>
              </Dropdown.SubMenu>
            </Dropdown.Group>
            <Dropdown.Separator />
            <Dropdown.SubMenu
              disabledWithReason="Exports open after the event ends"
              menu={<Dropdown.Item>Attendee list (CSV)</Dropdown.Item>}
            >
              <Dropdown.Item>Export</Dropdown.Item>
            </Dropdown.SubMenu>
          </>
        }
      >
        <Dropdown.Button size="md">Event</Dropdown.Button>
      </Dropdown>
      <p role="status">{status}</p>
    </div>
  );
};

/**
 * One choice of several: `Dropdown.RadioGroup` with the chosen `value` around
 * `Dropdown.RadioItem`s, the chosen one announced as checked. `textValue` is
 * what typeahead matches when a row's children (here an `Avatar`) aren't
 * text. `Dropdown.Search` filters a long list: you filter the rows, it
 * announces the count and shows the empty state. Enter picks the first match
 * and never submits a form. `onOpenChange` clears the search on close.
 */
const AssignSpeaker = () => {
  const [search, setSearch] = useState('');
  const [speaker, setSpeaker] = useState(speakers[0]);
  const matches = speakers.filter((name) =>
    name.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <Dropdown
      align="start"
      onOpenChange={(open) => {
        if (!open) setSearch('');
      }}
      menu={
        <>
          <Dropdown.Search
            label="Search speakers"
            placeholder="Search speakers"
            value={search}
            onChange={setSearch}
          />
          <Dropdown.RadioGroup value={speaker} onValueChange={setSpeaker}>
            {matches.map((name) => (
              <Dropdown.RadioItem
                key={name}
                value={name}
                textValue={name}
                leftAddOn={<Avatar name={name} size="sm" />}
              >
                {name}
              </Dropdown.RadioItem>
            ))}
          </Dropdown.RadioGroup>
        </>
      }
    >
      <Dropdown.Button>Speaker: {speaker}</Dropdown.Button>
    </Dropdown>
  );
};

/**
 * On/off options: `Dropdown.CheckboxItem` with `checked` and
 * `onCheckedChange`. Preventing the default in `onSelect` keeps the menu open,
 * so several can be toggled in a row. `showCheckbox` draws a checkbox before
 * each, `showCheckmark={false}` drops the check mark after it; with both on,
 * both show.
 */
const ViewOptions = () => {
  const [showSpeakers, setShowSpeakers] = useState(true);
  const [showVenue, setShowVenue] = useState(false);
  const keepOpen = (select: Event) => select.preventDefault();

  return (
    <Dropdown
      showCheckbox
      showCheckmark={false}
      menu={
        <Dropdown.Group label="Show on the agenda">
          <Dropdown.CheckboxItem
            checked={showSpeakers}
            onCheckedChange={setShowSpeakers}
            onSelect={keepOpen}
          >
            Speakers
          </Dropdown.CheckboxItem>
          <Dropdown.CheckboxItem
            checked={showVenue}
            onCheckedChange={setShowVenue}
            onSelect={keepOpen}
          >
            Venue
          </Dropdown.CheckboxItem>
        </Dropdown.Group>
      }
    >
      <Dropdown.Button>View</Dropdown.Button>
    </Dropdown>
  );
};

/**
 * `modal={false}` leaves the rest of the page usable while the menu is open;
 * leave it out unless that's needed. `rightIcon` replaces the chevron.
 */
const SortSessions = () => {
  const [sort, setSort] = useState('start');

  return (
    <Dropdown
      modal={false}
      align="start"
      menu={
        <Dropdown.RadioGroup
          label="Sort by"
          value={sort}
          onValueChange={setSort}
        >
          <Dropdown.RadioItem value="start">Start time</Dropdown.RadioItem>
          <Dropdown.RadioItem value="name">Session name</Dropdown.RadioItem>
        </Dropdown.RadioGroup>
      }
    >
      <Dropdown.Button rightIcon={<ArrowUpDown />}>
        Sort sessions
      </Dropdown.Button>
    </Dropdown>
  );
};

/**
 * An item that waits on work: `loadingWithReason` shows a spinner and says on
 * hover what it's doing. Preventing the default keeps the menu open, and the
 * controlled `open` closes it once the work is done.
 */
const PublishItem = () => {
  const [open, setOpen] = useState(false);
  const [isPublishing, setPublishing] = useState(false);

  return (
    <Dropdown
      open={open}
      onOpenChange={setOpen}
      menu={
        <Dropdown.Item
          loadingWithReason={isPublishing ? 'Publishing the agenda' : undefined}
          onSelect={(select) => {
            select.preventDefault();
            setPublishing(true);
            void fakeSave().then(() => {
              setPublishing(false);
              setOpen(false);
            });
          }}
        >
          Publish agenda
        </Dropdown.Item>
      }
    >
      <Dropdown.Button>Agenda</Dropdown.Button>
    </Dropdown>
  );
};

/**
 * The whole menu unavailable: `disabledWithReason` on the Dropdown disables
 * the trigger and says why in its tooltip. `loadingWithReason` shows a spinner
 * on the trigger and says why; `disableWhileLoading={false}` keeps the menu
 * usable meanwhile.
 */
const MenuStates = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Dropdown
      disabledWithReason="Sign in to manage tickets"
      menu={<Dropdown.Item>Refund ticket</Dropdown.Item>}
    >
      <Dropdown.Button>Tickets</Dropdown.Button>
    </Dropdown>
    <Dropdown
      loadingWithReason="Loading the venue map"
      disableWhileLoading={false}
      menu={<Dropdown.Item>Open venue map</Dropdown.Item>}
    >
      <Dropdown.Button>Venue</Dropdown.Button>
    </Dropdown>
  </div>
);

export default function DropdownRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <RowActions row={event} />
      <EventMenu />
      <AssignSpeaker />
      <ViewOptions />
      <SortSessions />
      <PublishItem />
      <MenuStates />
    </div>
  );
}

// packages/ui/src/Link/Link.recipe.tsx
// Covers: Link

/**
 * Link: text that takes the user to another page: another site, an email
 * (`mailto:`), a phone number (`tel:`) or a file. Inside text it has a dotted
 * line instead of an underline; a link that works as a control, such as a way
 * back, a breadcrumb or a navigation item, is `look="plain"`. In the Next
 * app, a route of the app is the app's NextLink, which looks the same and
 * navigates without reloading the page.
 *
 * When not to use:
 * - An action (save, delete, open a menu): Button. A link goes somewhere.
 * - A route of the Next app: its NextLink. One that must look like a button
 *   is `Button as={NextLink}`.
 * - A whole card that opens a page: Card with `stretchLink`.
 *
 * Pitfalls:
 * - The dotted line is for a link inside text only. A link that stands on its
 *   own as a control, such as a way back, a breadcrumb, a navigation item or a
 *   footer's links, is `look="plain"`.
 * - In the Next app, a route as Link reloads the whole page: use NextLink.
 * - `target="_blank"` needs `rel="noopener noreferrer"` and text saying it
 *   opens a new tab.
 * - Link text must make sense alone ("Event guidelines", not "Click here").
 * - Say why a link is disabled: `disabledWithReason` keeps it focusable and
 *   shows the reason on focus; a plain `disabled` link leaves the tab order.
 */
import { Link } from '@packages/ui/Link';
import React from 'react';

// Usage: the patterns to copy.
/** In a sentence: it sits inline and wraps with the text around it. */
const InText = () => (
  <p>
    Read the{' '}
    <Link href="https://example.com/code-of-conduct">code of conduct</Link>{' '}
    before you register.
  </p>
);

/**
 * Another site: Link. `target="_blank"` opens a new tab, so `rel` keeps the
 * new page from reaching this one, and visually hidden text tells screen
 * reader users.
 */
const ExternalSite = () => (
  <Link
    href="https://example.com/venues/harbor-hall"
    target="_blank"
    rel="noopener noreferrer"
  >
    Harbor Hall venue page
    <span className="sr-only"> (opens in a new tab)</span>
  </Link>
);

/**
 * A link that works as a control, here a footer's links: `look="plain"`, since
 * its place already says it is a link. The dotted line stays for links inside
 * text.
 */
const ControlLinks = () => (
  <nav aria-label="Help" className="flex-row-gap-4 flex-wrap">
    <Link look="plain" href="https://example.com/help">
      Help center
    </Link>
    <Link look="plain" href="https://example.com/status">
      Service status
    </Link>
  </nav>
);

/** An email address: `mailto:` opens the user's mail app. */
const Email = () => (
  <Link href="mailto:organizers@example.com">Email the organizers</Link>
);

/** A phone number: `tel:` offers to call it on a phone. */
const Phone = () => <Link href="tel:+31201234567">Call the venue</Link>;

/** A file: `download` saves it instead of opening it. */
const Download = () => (
  <Link href="/files/schedule.pdf" download>
    Download the schedule (PDF)
  </Link>
);

/**
 * Disabled with a reason: it can't be followed, and hovering or focusing it
 * says why.
 * `disabledWithReason` on its own disables it; `disabled` disables it
 * silently, for a link whose reason is obvious from the screen.
 */
const DisabledWithReason = () => (
  <Link
    href="/files/attendance-report.pdf"
    download
    disabledWithReason="Ready once the event has ended"
  >
    Attendance report (PDF)
  </Link>
);

export default function LinkRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <InText />
      <ExternalSite />
      <ControlLinks />
      <Email />
      <Phone />
      <Download />
      <DisabledWithReason />
    </div>
  );
}

// packages/ui/src/Typography/Typography.recipe.tsx
// Covers: Caption, Code, CodeBlock, DescriptionDetails, DescriptionList, DescriptionTerm, Kbd, List, ListItem, Mark, Paragraph, Quote, Separator, Time

/**
 * Typography: the text elements of a page, styled by the design system:
 * `Paragraph`, `Caption`, `List` with `ListItem`, `DescriptionList` with
 * `DescriptionTerm` and `DescriptionDetails`, `Quote`, `Code`, `CodeBlock`,
 * `Kbd`, `Mark`, `Separator` and `Time`.
 * - `color` (default, muted, primary or a status) replaces the color the
 *   text inherits. Every element but `Separator` takes it.
 * - `font` (ui, display or mono) replaces the font the text inherits.
 *   `Code`, `CodeBlock` and `Kbd` are always mono, and `Separator` has no
 *   text, so these four don't take it.
 * - Size and line height are fixed: the caption's for `Caption`, the
 *   surrounding text's for `Code`, `Kbd`, `Mark` and `Time`, and the body's
 *   for the others.
 *
 * When not to use:
 * - A heading: a `Section`'s title is the heading.
 * - A line between groups: a gap between them is usually enough. Use a
 *   `Separator` only where the groups need a visible line.
 * - A list of records: a `CardList` or a `Table`. A `List` is for text.
 * - Rows people sort, filter or compare across: a `Table`.
 * - A number people read and compare: a `Numeral`, inside the text element.
 *
 * Pitfalls:
 * - Spacing between paragraphs and lists comes from their parent's gap,
 *   such as `flex-col-gap-3`: the elements have no margins.
 * - `ordered` only when the order means something, such as steps.
 * - A `CodeBlock` takes the code as a string: keep its line breaks in a
 *   template literal.
 */
import { Numeral } from '@packages/ui/Numeral';
import {
  Caption,
  Code,
  CodeBlock,
  DescriptionDetails,
  DescriptionList,
  DescriptionTerm,
  Kbd,
  List,
  ListItem,
  Mark,
  Paragraph,
  Quote,
  Separator,
  Time,
} from '@packages/ui/Typography';
import React from 'react';

// Setup: stand-ins for your app's data, not part of the pattern.
const record = [
  { label: 'Created', value: '2 Nov 2026' },
  { label: 'Status', value: 'Active' },
  { label: 'Owner', value: 'Alex Morgan' },
];
const setup = `pnpm install
pnpm dev`;

// Usage: the patterns to copy.
/** Body text: paragraphs in a column, spaced by the parent's gap. */
const Text = () => (
  <div className="flex-col-gap-3">
    <Paragraph>
      A paragraph of body text, which wraps to the width of its column.
    </Paragraph>
    <Paragraph color="muted">A muted paragraph for a detail.</Paragraph>
  </div>
);

/** A small muted line on the text above it, such as when a record was made. */
const Note = () => (
  <div className="flex-col-gap-1">
    <Paragraph>Spring launch plan</Paragraph>
    <Caption>Updated 2 Nov 2026</Caption>
  </div>
);

/** Points in any order, bulleted. An item may hold a list of its own. */
const Points = () => (
  <List>
    <ListItem>First point</ListItem>
    <ListItem>
      Second point
      <List>
        <ListItem>A point under it</ListItem>
      </List>
    </ListItem>
  </List>
);

/** Steps the reader follows in order, numbered. */
const Steps = () => (
  <List ordered>
    <ListItem>Fill in the form</ListItem>
    <ListItem>Check the details</ListItem>
    <ListItem>Confirm</ListItem>
  </List>
);

/** A record's fields as label and value pairs, one pair a row. */
const Fields = () => (
  <DescriptionList>
    {record.map(({ label, value }) => (
      <div key={label}>
        <DescriptionTerm>{label}</DescriptionTerm>
        <DescriptionDetails>{value}</DescriptionDetails>
      </div>
    ))}
    <div>
      <DescriptionTerm>Items</DescriptionTerm>
      <DescriptionDetails>
        <Numeral>1,300</Numeral>
      </DescriptionDetails>
    </div>
  </DescriptionList>
);

/** Someone's words, with who said them. Without `source`, just the quote. */
const Testimonial = () => (
  <Quote source="Alex Morgan" font="display">
    Someone's words, as they said them.
  </Quote>
);

/** Code in a sentence, and lines of code on their own. */
const Commands = () => (
  <div className="flex-col-gap-3">
    <Paragraph>
      Start the app with <Code>pnpm dev</Code> once the packages are in.
    </Paragraph>
    <CodeBlock>{setup}</CodeBlock>
  </div>
);

/** A shortcut named in a sentence. */
const Shortcut = () => (
  <Paragraph>
    Press <Kbd>Ctrl K</Kbd> to search.
  </Paragraph>
);

/** A search result's line, with the words that match the search marked. */
const SearchResult = () => (
  <Paragraph>
    Spring <Mark>launch</Mark> plan
  </Paragraph>
);

/**
 * A line between two groups of text that need one, and between items in a
 * row, where the row stretches it to its height.
 */
const Groups = () => (
  <div className="flex-col-gap-3">
    <Paragraph>Delivery by courier, in 3 to 5 days.</Paragraph>
    <Separator />
    <div className="flex-row-gap-3">
      <Paragraph>2 items</Paragraph>
      <Separator orientation="vertical" />
      <Paragraph>Paid by card</Paragraph>
    </div>
  </div>
);

/**
 * A record's date or moment, from the ISO value it keeps: one format across
 * the app. `withTime` adds the time of day to a moment.
 */
const Dates = () => (
  <Paragraph>
    Placed <Time value="2026-11-07" />, shipped{' '}
    <Time value="2026-11-09T10:30:00.000Z" withTime />.
  </Paragraph>
);

export default function TypographyRecipe() {
  return (
    <div className="flex-col-gap-6">
      <Text />
      <Note />
      <Points />
      <Steps />
      <Fields />
      <Testimonial />
      <Commands />
      <Shortcut />
      <SearchResult />
      <Groups />
      <Dates />
    </div>
  );
}

