          <li key={session} className="flex-row-gap-2 items-center">
            {session}
            <IconButton
              variant="danger"
              look="ghost"
              tooltip="Delete"
              aria-label={`Delete ${session}`}
              onClick={() => {
                addRef.current?.focus();
                setSessions((current) =>
                  current.filter((entry) => entry !== session),
                );
              }}
            >
              <Trash2 />
            </IconButton>
          </li>
        ))}
      </ul>
      <Button
        ref={addRef}
        leftIcon={<Plus />}
        onClick={() => setSessions((current) => [...current, 'New session'])}
      >
